cd /logs/agent/sessions/skills/xlsx && python3 -c "
import openpyxl
wb = openpyxl.load_workbook('/root/test - demand.xlsx', data_only=True)
ws = wb['NA']

print('=== Scenario 1 (Base Case) ===')
for r in range(6, 35):
    b = ws.cell(r, 2).value
    if b:
        vals = []
        for c in [4,5,6,7,8,9,10,11,12]:  # 2025-2033
            v = ws.cell(r, c).value
            if v is not None:
                if isinstance(v, float) and abs(v) < 1:
                    vals.append(f'{v:.4f}')
                elif isinstance(v, float):
                    vals.append(f'{v:.3f}')
                else:
                    vals.append(str(v))
            else:
                vals.append('')
        print(f'Row {r}: {b:40s} | {\" | \".join(vals[:5])}')
        if len(vals) > 5:
            print(f'       {\" \":40s} | {\" | \".join(vals[5:])}')
"
